java.util.function.Function<Integer, Integer> twice = x -> x * 2;
java.util.function.Predicate<Integer> large = x -> x >= 10;
System.out.println(large.test(twice.apply(6)));

var result = java.util.List.of(6, 1, 4, 3).stream()
        .filter(x -> x >= 3)
        .map(x -> x * 2)
        .sorted()
        .toList();
System.out.println(result);

String label = java.util.List.of("elm", "ash").stream()
        .filter(name -> name.startsWith("z"))
        .findFirst()
        .map(String::toUpperCase)
        .orElse("NO MATCH");
System.out.println(label);
